import"./chunk-2NFLSA4Y.js";var a={lagrange:{theory:{concept:"[[Lagrange points are the five points in the orbital plane of two bodies circling each other where a small third body can stay at rest relative to both: there the combined gravity of the two bodies gives exactly the force needed to go round together with them.]] L1, L2 and L3 lie on the line through the two bodies and are unstable: like a pencil balanced on its tip, an object there drifts away unless it corrects its position. L4 and L5 form equilateral triangles with the two bodies and are stable when one body is much heavier than the other (mass ratio \u03BC < 0.0385); thousands of asteroids have gathered at Jupiter\u2019s L4 and L5 points."},section:{history:{title:"Euler and Lagrange",text:"In 1767 Leonhard Euler found three points on the line through the two bodies (L1, L2, L3). In 1772 Joseph-Louis Lagrange found two more (L4, L5), at the tips of equilateral triangles. For more than a century they were mathematical curiosities \u2014 until the first asteroid was found sitting at Jupiter's L4 point in 1906."},rotating:{title:"Seen from a turning frame",text:"Imagine you ride along with the two bodies, so they stay still. In this turning frame a small object feels the pull of both bodies and an outward centrifugal push. The landscape on the screen shows this combined effective potential: wells at the bodies, saddles at L1, L2 and L3, hilltops at L4 and L5. At the five points all these forces cancel, so an object at rest stays at rest."},points:{title:"Where the five points are",text:"[[L1 lies between the two bodies, L2 just beyond the smaller one, and L3 on the far side of the bigger one.]] L1 and L2 are about a\xB7\u221B(\u03BC/3) from the small body \u2014 1.5 million km for the Earth, about 60 000 km for the Moon. L4 and L5 lie on the small body's orbit, 60\xB0 ahead and 60\xB0 behind it."},stability:{title:"Balancing \u2014 stable or not?",text:"[[L1, L2 and L3 are saddles: the slightest push grows and the object drifts away.]] L4 and L5 are hilltops, so one would expect them to be unstable too \u2014 but the Coriolis force turns a falling object sideways into a loop around the point. This works only if the small body is light enough: \u03BC below 0.0385 (Routh's limit). Above it, even L4 and L5 lose their objects."},missions:{title:"Spacecraft at Lagrange points",text:"SOHO has watched the Sun from Sun\u2013Earth L1 since 1996. The James Webb Space Telescope has worked near L2 since 2022, far from the Earth's heat, with the Sun, Earth and Moon always behind its sunshield. Because L1 and L2 are unstable, these spacecraft fly in loops (halo orbits) around the points and fire small thrusters every few weeks. China's Queqiao relay satellite circles Earth\u2013Moon L2 to talk to landers on the far side of the Moon."},trojans:{title:"Trojans",text:"Objects gathered at L4 and L5 are called Trojans. Jupiter has more than ten thousand, swarming 60\xB0 ahead of and behind it; NASA's Lucy spacecraft, launched in 2021, is on its way to visit several. The Earth has at least two small Trojan asteroids, 2010 TK7 and 2020 XL5. Trojans do not sit still: they slowly loop around the point in tadpole-shaped paths."},check:{title:"Check your understanding",text:"Why does JWST need thrusters at L2? Why are there Trojans at Jupiter's L4 and L5 but none at its L1? What would happen to the Trojans if Jupiter were 50 times heavier? Try each answer in the simulation."}},formula:{triangle:"L4 and L5 are the same distance a from both bodies (equilateral triangles)",hill:"Distance of L1 and L2 from the small body (a: separation of the bodies)",routh:"Routh's limit: L4 and L5 are stable only below this mass ratio",potential:"Effective potential in the turning frame (units: a = 1, total mass = 1)",motion:"Equations of motion with the Coriolis terms 2\u1E8B, 2\u1E8F",jacobi:"Jacobi constant: stays the same along any path"},variable:{mu:"Mass ratio: small body \xF7 total mass",a:"Distance between the two bodies",r:"Distances from the big and the small body"},assumption:{circular:"The two bodies move on circles in one plane; the test particles are so light that they do not pull back.",landscape:"The landscape shows the effective potential with exaggerated heights. A marble on a real surface like this would roll off L4 and L5 \u2014 here the Coriolis force keeps it in a loop.",scale:"Bodies and particles are drawn much larger than scale.",ends:"A particle that hits a body or flies three separations away is removed."},param:{system:"System",target:"Release at",nudge:"Nudge from the point",mu:"Mass ratio \u03BC",cloud:"Cloud of particles",timeScale:"Time speed-up \xD7"},hint:{target:"Where the test particles start, at rest in the turning frame.",nudge:"How far from the exact point, in % of its distance to the nearer body.",mu:"The small body's share of the total mass. Above 0.0385 even L4 and L5 are unstable.",cloud:"Twelve particles in a ring around each chosen point."},preset:{sunEarth:"Sun \u2013 Earth",earthMoon:"Earth \u2013 Moon",sunJupiter:"Sun \u2013 Jupiter",custom:"Custom",all:"All five",L1:"L1",L2:"L2",L3:"L3",L4:"L4",L5:"L5",light:"Light",routh:"Routh's limit",heavy:"Heavy",twins:"Equal masses"},measure:{revolutions:"Revolutions of the system",years:"Real time (years)",drift:"Largest drift from a point",nearCount:"Particles still near their point",alive:"Particles left",mu:"Mass ratio",pointDistance:"Distance of the point from the small body",jacobiError:"Change of the Jacobi constant",jacobi:"Jacobi constant"},view:{stable:"\u03BC = {mu} < {routh}: L4 and L5 are stable",unstable:"\u03BC = {mu} > {routh}: even L4 and L5 are unstable",timeYears:"{revolutions} revolutions \xB7 {years} years",time:"{revolutions} revolutions",zoomOption:"Close-up of the small body",surfaceOption:"Potential landscape",contoursOption:"Contour lines through L1\u2013L3",markersOption:"Lagrange points"},graph:{drift:"Drift against time",jacobi:"Jacobi constant against time"},challenge:{jwst:{title:"Why JWST needs thrusters",description:"Release a particle at Sun\u2013Earth L2, where the James Webb Space Telescope works, and watch it drift away.",hint:"Choose Sun \u2013 Earth and L2. Turn on the close-up to see L1 and L2."},trojans:{title:"Jupiter's Trojans",description:"Keep a particle near Jupiter's L4 or L5 for 10 revolutions.",hint:"Choose Sun \u2013 Jupiter and L4 or L5 with a small nudge."},onlyTwo:{title:"Who stays?",description:"Release one particle at each of the five points and watch for 3 revolutions. Only two should stay.",hint:"Which points are saddles, and which are protected by the Coriolis force?"},routh:{title:"Too heavy",description:"Make the small body so heavy that even a particle at L4 or L5 drifts away.",hint:"Choose a custom system with \u03BC above 0.0385."},edge:{title:"On the edge",description:"With \u03BC between 0.02 and 0.0385, keep a particle at L4 or L5 for 10 revolutions.",hint:"Just below Routh's limit the loops are wide, so keep the nudge small."},swarm:{title:"A Trojan swarm",description:"Release a cloud of particles at Jupiter's L4 or L5 and keep them all for 10 revolutions.",hint:"Turn on the cloud; keep the nudge small."}}}},o={sim:a};export{o as default,a as sim};
